//! Components of the ECS cow (generated by `gen/groups.py` from the fields of `Mob`; see suivi/ecs-prototype.md).
#![allow(missing_docs)]
use crate::mobs::*;
use crate::mobs::{anim, combat};
use super::extra::CowExtra;
use bevy_ecs::component::Component;
use std::sync::Arc;
use horizon_core::{geometry::Vec3, random::EntityRandom};

#[derive(Component, Clone, Debug)]
pub struct Ident {
    pub id: u32,
    pub kind: Arc<MobType>,
}

#[derive(Component, Clone, Debug)]
pub struct Motion {
    pub position: Vec3,
    pub previous: Vec3,
    pub velocity: Vec3,
    pub yaw: f32,
    pub previous_yaw: f32,
    pub body_yaw: f32,
    pub previous_body_yaw: f32,
    pub head_yaw: f32,
    pub previous_head_yaw: f32,
    pub head_pitch: f32,
    pub previous_head_pitch: f32,
    pub on_ground: bool,
    pub horizontal_collision: bool,
    pub vertical_collision_below: bool,
    pub needs_sync: bool,
    pub sync_position: bool,
    pub fall_distance: f64,
    pub stuck_multiplier: Vec3,
    pub piston: horizon_world::piston_movement::PistonMovement,
    pub supporting: Option<[i32; 3]>,
    pub climbing: bool,
    pub on_climbable: bool,
    pub no_gravity: bool,
    pub no_physics: bool,
    pub pushed: Vec<u32>,
    pub limb_position: f32,
    pub limb_speed: f32,
    pub previous_limb_speed: f32,
}

#[derive(Component, Clone, Debug)]
pub struct Vitals {
    pub health: f32,
    pub hurt_time: i32,
    pub invulnerable: i32,
    pub invulnerable_time: i32,
    pub death_time: i32,
    pub impulse_grace_time: i32,
    pub absorption: f32,
    pub last_hurt: f32,
    pub dealt_absorbed: i32,
    pub last_damage: Option<(Damage, i64)>,
    pub accepted_hit: Option<std::sync::Arc<crate::health::AcceptedHit>>,
    pub death_canceled: bool,
    pub last_direct: Option<&'static str>,
    pub attacker_aim: Option<Aim>,
    pub creative_attacker: bool,
    pub projectile_motion: Option<[f64; 2]>,
    pub invulnerable_flag: bool,
    pub combat: combat::Tracker,
    pub removed: bool,
    pub despawn: mod_api::Despawn,
    pub gear_knockback_resistance: Option<f64>,
}

#[derive(Component, Clone, Debug)]
pub struct Env {
    pub fire_ticks: i32,
    pub ticks_frozen: i32,
    pub in_powder_snow: bool,
    pub air: i32,
    pub first_tick: bool,
    pub was_eye_in_water: bool,
}

#[derive(Component, Clone, Debug)]
pub struct Clk {
    pub age: u32,
    pub ambient_timer: i32,
    pub persistent: bool,
    pub no_ai: bool,
    pub silent: bool,
    pub swell: i32,
    pub previous_swell: i32,
    pub max_swell: i32,
}

#[derive(Component, Clone, Debug)]
pub struct Rand(pub EntityRandom);
impl std::ops::Deref for Rand {
    type Target = EntityRandom;
    fn deref(&self) -> &EntityRandom {
        &self.0
    }
}
impl std::ops::DerefMut for Rand {
    fn deref_mut(&mut self) -> &mut EntityRandom {
        &mut self.0
    }
}

